        if winner:
            ui.draw(game)
            ui.show_message("*** {} ({}) wins with five in a row! ***".format(
                game.name(winner), game.stone(winner)))
            break
        if game.is_full():
            ui.draw(game)
            ui.show_message("Draw! The board is full.")
            break
        game.switch_player()


